const TAG_ID = "G-XXXXXXXXXX"; // your Google tag ID
const TYPES = ["ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"];

export function initConsent(): void {
  const w = window as unknown as { dataLayer: unknown[]; __consentInit?: boolean };
  if (w.__consentInit) return;
  w.__consentInit = true;
  // the browser hides the nonce attribute but keeps the .nonce property of an existing nonce'd script
  const NONCE = (document.querySelector("script[nonce]") as HTMLScriptElement | null)?.nonce || "";
  w.dataLayer = w.dataLayer || [];
  function gtag(..._args: unknown[]) { w.dataLayer.push(arguments); } // Google's tag needs the real `arguments` object
  const state = (v: string) => Object.fromEntries(TYPES.map((t) => [t, v]));
  gtag('consent', 'default', state("denied")); // before any Google tag request
  const stored = () => document.cookie.match(/(?:^|; )consent=(granted|denied)/)?.[1] ?? null;
  const store = (v: string) => {
    document.cookie = `consent=${v}; Max-Age=31536000; Path=/; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}`;
  };
  let loaded = false;
  function loadTag() {
    if (loaded) return;
    loaded = true;
    const s = document.createElement("script");
    s.async = true;
    if (NONCE) s.nonce = NONCE;
    s.src = "https://www.googletagmanager.com/gtag/js?id=" + encodeURIComponent(TAG_ID);
    document.head.appendChild(s);
    gtag('js', new Date());
    gtag('config', TAG_ID);
  }
  function apply(v: string) {
    if (v === "granted") { gtag('consent', 'update', state("granted")); loadTag(); }
    else gtag('consent', 'update', state("denied"));
  }
  const banner = document.getElementById("consent-banner");
  const reopen = document.getElementById("consent-reopen");
  const show = (on: boolean) => { if (banner) banner.hidden = !on; if (reopen) reopen.hidden = on; };
  document.addEventListener("click", (e) => {
    const t = e.target as Element | null;
    const b = t?.closest?.("[data-consent]");
    if (b) { const v = b.getAttribute("data-consent") || "denied"; store(v); apply(v); show(false); }
    else if (t?.closest?.("#consent-reopen")) show(true);
  });
  const prior = stored();
  if (prior) { apply(prior); show(false); }
  else { if ((navigator as unknown as { globalPrivacyControl?: boolean }).globalPrivacyControl === true) apply("denied"); show(true); }
}

