import type { ReactNode } from "react";
import { isRouteErrorResponse, Link, Links, Meta, Outlet, Scripts, ScrollRestoration } from "react-router";
import type { Route } from "./+types/root";

export function Layout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <Meta />
        <Links />
      </head>
      <body>
        <header>
          <nav aria-label="Main">
            <Link to="/">Home</Link> <Link to="/posts">Posts</Link>
          </nav>
        </header>
        <main>{children}</main>
        <footer><Link to="/privacy">Privacy</Link></footer>
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  );
}

export default function App() {
  return <Outlet />;
}

export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
  const status = isRouteErrorResponse(error) ? error.status : 500; // the response status is already this value
  const title =
    status === 404 ? "Page not found" : status === 410 ? "This page has been removed" : status === 503 ? "Temporarily unavailable" : "Something went wrong";
  return (
    <section>
      <title>{title}</title>
      {/* React 19 hoists <title> and <meta> into <head> */}
      <meta name="robots" content="noindex" />
      <h1>{title}</h1>
      {status === 404 ? <p>We could not find that page.</p> : <p>Please try again in a moment.</p>}
      <p><Link to="/">Back to the home page</Link></p>
    </section>
  ); // generic text only: never print error.message or error.stack
}

