import { data } from "react-router";
import type { Route } from "./+types/post";
import { db } from "../db.server"; // placeholder DB client

export async function loader({ params }: Route.LoaderArgs) {
  let post;
  try {
    post = await db.posts.findBySlug(params.slug);
  } catch {
    throw data(null, { status: 503 }); // dependency down: 5xx, never 404 and never a 200 fallback
  }
  if (!post) throw data(null, { status: 404 }); // unknown slug, including probe values like sg-probe-404
  return { post };
}

export default function Post({ loaderData }: Route.ComponentProps) {
  return <article><h1>{loaderData.post.title}</h1></article>;
}

React Router v8 framework mode. A route `action` behind a plain `<Form method="post">`: works without JavaScript (303 on success, 502 page on delivery failure, status taken from `data(..., { status })`). React Router already rejects cross-origin action posts to UI routes (`allowedActionOrigins` in react-router.config.ts widens it); the explicit Origin check below also covers proxies and older versions. The in-memory limiter is a placeholder for Redis/Upstash.
