import { data, Form, redirect } from "react-router";
import type { Route } from "./+types/contact";

const hits = new Map<string, number[]>(); // placeholder for Redis/Upstash
const LIMIT = 5;
const WINDOW_MS = 10 * 60 * 1000;

function tooMany(ip: string): boolean {
  const now = Date.now();
  const recent = (hits.get(ip) ?? []).filter((t) => now - t < WINDOW_MS);
  recent.push(now);
  hits.set(ip, recent);
  return recent.length > LIMIT;
}

function sameSite(request: Request): boolean {
  const origin = request.headers.get("Origin"); // SEC-024
  if (origin) return origin === new URL(process.env.SITE_URL ?? request.url).origin;
  return request.headers.get("Sec-Fetch-Site") === "same-origin";
}

export function loader({ request }: Route.LoaderArgs) {
  return { sent: new URL(request.url).searchParams.get("sent") === "1" };
}

export async function action({ request }: Route.ActionArgs) {
  if (!sameSite(request)) throw data("Forbidden", { status: 403 });
  // only trust x-forwarded-for when your proxy sets it
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";
  if (tooMany(ip)) return data({ error: "Too many messages, please try again later." }, { status: 429 }); // SEC-054/055

  const form = await request.formData();
  if (String(form.get("website") ?? "") !== "") return redirect("/contact?sent=1", 303); // honeypot: success-looking, no side effect
  const name = String(form.get("name") ?? "").trim();
  const email = String(form.get("email") ?? "").trim();
  const message = String(form.get("message") ?? "").trim();
  if (!name || name.length > 100 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254 || !message || message.length > 5000) {
    return data({ error: "Please check the form and try again." }, { status: 400 });
  }
  try {
    const res = await fetch(process.env.FORM_WEBHOOK_URL!, { // the one line the project replaces (email API / CRM / DB insert)
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name, email, message }),
      signal: AbortSignal.timeout(8000),
    });
    if (!res.ok) throw new Error(`webhook ${res.status}`);
  } catch {
    return data({ error: "Your message could not be sent. Please try again later." }, { status: 502 }); // never a success message on failure
  }
  return redirect("/contact?sent=1", 303); // PRG
}

export default function Contact({ loaderData, actionData }: Route.ComponentProps) {
  if (loaderData.sent) return <p role="status">Thanks, your message was sent.</p>;
  return (
    <Form method="post">
      {actionData?.error ? <p role="alert">{actionData.error}</p> : null}
      <label>Name <input name="name" autoComplete="name" required maxLength={100} /></label>
      <label>Email <input name="email" type="email" autoComplete="email" required maxLength={254} /></label>
      <label>Message <textarea name="message" required maxLength={5000} /></label>
      {/* off-screen via .hp in app.css (no inline styles under the CSP): .hp { position: absolute; left: -10000px } */}
      <div className="hp" aria-hidden="true">
        <label>Website <input name="website" tabIndex={-1} autoComplete="off" /></label>
      </div>
      {/* Cloudflare Turnstile alternative: render the widget and verify cf-turnstile-response server-side */}
      <p>By sending this form you accept our <a href="/privacy">privacy notice</a>.</p>
      <button type="submit">Send</button>
    </Form>
  );
}

React Router v8 framework mode (same code on v7.18). `entry.server.tsx` makes a fresh nonce per document response, passes it to `<ServerRouter nonce>` (Scripts and ScrollRestoration inherit it) and to `renderToPipeableStream`, and sets the headers. Keep `status: responseStatusCode`: a loader that throws arrives here as 500, so never hard-code 200 (RTE-007). Reveal the stock file with `npx react-router reveal` and merge.
### file: app/entry.server.tsx
import { PassThrough } from "node:stream";
import { randomBytes } from "node:crypto";
import type { EntryContext } from "react-router";
import { createReadableStreamFromReadable } from "@react-router/node";
import { ServerRouter } from "react-router";
import { isbot } from "isbot";
import { renderToPipeableStream } from "react-dom/server";

export const streamTimeout = 5_000;

// Hashed assets under build/client/assets: react-router-serve already sends "public, max-age=31536000, immutable";
// on any other server or CDN add that rule for /assets/* yourself (it is not set from here).
function setSecurityHeaders(headers: Headers, request: Request, nonce: string) {
  headers.set(
    "Content-Security-Policy",
    [
      "default-src 'self'",
      `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'`, // no Google hosts here: the consent loader's tag is trusted via strict-dynamic
      `style-src 'self' 'nonce-${nonce}'`,
      "img-src 'self' data:",
      "font-src 'self'",
      "connect-src 'self'", // analytics beacons (google-analytics.com ...) go here only, see the consent recipe
      "object-src 'none'",
      "base-uri 'self'",
      "form-action 'self'",
      "frame-ancestors 'none'",
      "upgrade-insecure-requests",
    ].join("; "),
  );
  headers.set("X-Content-Type-Options", "nosniff");
  headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  if (new URL(request.url).protocol === "https:" || request.headers.get("x-forwarded-proto") === "https") {
    headers.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains");
  }
  // HTML cache policy (PRF-008); a route `headers` export may set its own (private, no-store for personalised pages)
  if (!headers.has("Cache-Control")) headers.set("Cache-Control", "public, max-age=0, must-revalidate");
}

export default function handleRequest(
  request: Request,
  responseStatusCode: number,
  responseHeaders: Headers,
  routerContext: EntryContext,
) {
  const nonce = randomBytes(16).toString("base64"); // fresh per response (SEC-010, SEC-075)
  setSecurityHeaders(responseHeaders, request, nonce);

  if (request.method.toUpperCase() === "HEAD") {
    return new Response(null, { status: responseStatusCode, headers: responseHeaders });
  }

  return new Promise((resolve, reject) => {
    let shellRendered = false;
    const userAgent = request.headers.get("user-agent");
    // crawlers get the complete page, not a streamed shell
    const readyOption: "onAllReady" | "onShellReady" =
      (userAgent && isbot(userAgent)) || routerContext.isSpaMode ? "onAllReady" : "onShellReady";
    const timeoutId = setTimeout(() => abort(), streamTimeout + 1000);

    const { pipe, abort } = renderToPipeableStream(
      <ServerRouter context={routerContext} url={request.url} nonce={nonce} />,
      {
        nonce,
        [readyOption]() {
          shellRendered = true;
          const body = new PassThrough({
            final(callback) {
              clearTimeout(timeoutId);
              callback();
            },
          });
          responseHeaders.set("Content-Type", "text/html");
          pipe(body);
          resolve(
            new Response(createReadableStreamFromReadable(body), {
              headers: responseHeaders,
              status: responseStatusCode, // 404/410/500/503 chosen by React Router from the thrown value
            }),
          );
        },
        onShellError(error: unknown) {
          reject(error);
        },
        onError(error: unknown) {
          responseStatusCode = 500;
          if (shellRendered) console.error(error);
        },
      },
    );
  });
}

