// Add to the existing root route: every response off-production carries X-Robots-Tag (IDX-005); production sends nothing.
import type { Route } from "./+types/root";

export const middleware: Route.MiddlewareFunction[] = [
  async (_args, next) => {
    const response = await next();
    if (process.env.DEPLOY_ENV !== "production") response.headers.set("X-Robots-Tag", "noindex, nofollow");
    return response;
  },
];
